/* ===== Oct 28 2026 patch: home hero A/B test (A = photo hero with buttons, B = live Vibe Map hero) ===== */
/* Assigned 50/50 on the first home page view and kept in localStorage "fc-hero". ?hero=a or ?hero=b forces one.
   Every event and lead from that browser carries "hero=a" or "hero=b" at the end of its utm field. */
function heroVar(assign){
  try{
    const q=new URLSearchParams(location.search).get("hero");
    if(q==="a"||q==="b"){localStorage.setItem("fc-hero",q);return q;}
    let v=localStorage.getItem("fc-hero");
    if(!v&&assign){v=Math.random()<.5?"a":"b";localStorage.setItem("fc-hero",v);}
    return v||null;
  }catch(e){return null;}
}
function fcUtm(u){const v=heroVar();return v?((u?u+"&":"")+"hero="+v).slice(0,300):u;}
/* Towns for the Vibe Map save box: the picked vibe's towns, lead vibe first, then by how many vibes they share. */
function vibeTop(){
  const v=S.vibe;if(!v)return [];
  return T.filter(t=>t.vibes.includes(v)).sort((a,b)=>(b.vibes[0]===v)-(a.vibes[0]===v)||a.vibes.indexOf(v)-b.vibes.indexOf(v)).slice(0,5).map(e=>({e:e,f:null}));
}
let hvSeen=false;
function homeMapFoot(){
  if(heroVar()!=="b")return '<p style="margin-top:18px;text-align:center"><a class="more" href="#map">Open the full Vibe Map</a></p>';
  if(!S.vibe)return '<div class="hvhint"><span>Tap a vibe above and watch the coast light up.</span><a class="more" href="#map">Open the full Vibe Map</a></div>';
  hvSeen||(hvSeen=true,track("popup_shown","handoff"));
  const nm=VIBES[S.vibe]||"this vibe",tn=vibeTop().map(x=>short(x.e)),tl=tn.length>1?tn.slice(0,-1).join(", ")+" and "+tn[tn.length-1]:tn[0]||"";
  const save=S.sent.vibe?'<div class="savebox sent" role="status"><b>Saved. Your towns and the guide are on the way.</b><span>Check your inbox in a few minutes. Questions? Just reply to that email.</span></div>'
    :`<form class="savebox leadform hvsave" data-lead="matches" data-key="vibe">${hpField}<div class="sv-hd"><b>Keep these towns</b><span><strong>${tl}</strong> in your inbox, each with its prices, flood notes and airport drive, plus our free Move and Belong Guide.</span></div><div class="sv-row"><label for="hv-e" class="sr-only">Your email</label><input id="hv-e" name="email" type="email" autocomplete="email" inputmode="email" placeholder="you@example.com" required><button class="btn btn-accent" type="submit">Send them</button></div><p class="sv-note">No spam, no sales calls.</p></form>`;
  return `<div class="hvfoot"><div class="hvrank"><div><b>Like ${nm}? Want these ranked for you?</b><span>${SQ.length} taps, 2 minutes, no sign up. We'll score every town on how you want to live.</span></div><a class="btn btn-accent" href="#quiz" data-handoff="1">Rank my towns</a></div>${save}<p style="margin-top:14px;text-align:center"><a class="more" href="#map">Open the full Vibe Map</a></p></div>`;
}
